using System;using System.Reflection;using UnityEditor;
using System.Linq;
public static class EditorTestSettings {
 const BindingFlags Flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static;
 public static object Inspect(){var a=typeof(EditorWindow).Assembly;var log=a.GetType("UnityEditor.LogEntries");var c=a.GetType("UnityEditor.ConsoleWindow");return new{log=log?.FullName,methods=log?.GetMethods(Flags).Select(m=>m.Name).ToArray(),properties=log?.GetProperties(Flags).Select(m=>m.Name).ToArray(),nested=c?.GetNestedTypes(BindingFlags.Public|BindingFlags.NonPublic).Select(t=>t.Name).ToArray()};}
 public static object Disable(){var a=typeof(EditorWindow).Assembly;var log=a.GetType("UnityEditor.LogEntries");var c=a.GetType("UnityEditor.ConsoleWindow").GetNestedType("ConsoleFlags",BindingFlags.Public|BindingFlags.NonPublic);int flag=(int)Enum.Parse(c,"ErrorPause"),all=(int)log.GetProperty("consoleFlags",Flags).GetValue(null);if(!SessionState.GetBool("ViewAction/errorPauseSaved",false)){SessionState.SetBool("ViewAction/errorPause",(all&flag)!=0);SessionState.SetBool("ViewAction/errorPauseSaved",true);}log.GetMethod("SetConsoleFlag",Flags).Invoke(null,new object[]{flag,false});EditorApplication.isPaused=false;return new{old=(all&flag)!=0,enabled=false};}
 public static object Restore(){var a=typeof(EditorWindow).Assembly;var log=a.GetType("UnityEditor.LogEntries");var c=a.GetType("UnityEditor.ConsoleWindow").GetNestedType("ConsoleFlags",BindingFlags.Public|BindingFlags.NonPublic);int flag=(int)Enum.Parse(c,"ErrorPause");bool old=SessionState.GetBool("ViewAction/errorPause",false);if(SessionState.GetBool("ViewAction/errorPauseSaved",false)){log.GetMethod("SetConsoleFlag",Flags).Invoke(null,new object[]{flag,old});SessionState.EraseBool("ViewAction/errorPauseSaved");}return new{restored=old};}
}
